// by atomically advancing its completion offset. It runs inside a transaction where it fetches the
// attached function (with a row lock), the associated function record, and the collection record, then
// calls UpdateCompletionOffsetAndHeapEntry.
//
//   - If UpdateCompletionOffsetAndHeapEntry reports that the offset would regress, the error is propagated.
//   - If the collection's current log position is strictly ahead of the new completion offset, the result
//     is NeedsRepair (carrying the collection's current log offset).
//   - Otherwise the result is Success (carrying the new completion offset).
func (s *Coordinator) TryFinishAsyncAttachedFunctionInvocation(ctx context.Context, req *coordinatorpb.TryFinishAsyncAttachedFunctionInvocationRequest) (*coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse, error) {
	log := log.With(zap.String("method", "TryFinishAsyncAttachedFunctionInvocation"))

	attachedFunctionID, err := uuid.Parse(req.AttachedFunctionId)
	if err != nil {
		log.Error("TryFinishAsyncAttachedFunctionInvocation: invalid attached_function_id", zap.Error(err))
		return nil, status.Errorf(codes.InvalidArgument, "invalid attached_function_id: %v", err)
	}

	newOffset := int64(req.NewCompletionOffset)

	response := &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse{}

	err = s.catalog.txImpl.Transaction(ctx, func(txCtx context.Context) error {
		// 1. Fetch the attached function by ID (with a row lock).
		attachedFunctions, err := s.catalog.metaDomain.AttachedFunctionDb(txCtx).GetAttachedFunctions(&attachedFunctionID, nil, nil, false)
		if err != nil {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: failed to get attached function", zap.Error(err))
			return err
		}
		if len(attachedFunctions) == 0 {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: attached function not found")
			return common.ErrAttachedFunctionNotFound
		}
		attachedFunction := attachedFunctions[0]

		// 2. Retrieve the associated function record.
		function, err := s.catalog.metaDomain.FunctionDb(txCtx).GetByID(attachedFunction.FunctionID)
		if err != nil {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: failed to get function", zap.Error(err))
			return err
		}
		if function == nil {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: function not found", zap.String("function_id", attachedFunction.FunctionID.String()))
			return common.ErrFunctionNotFound
		}

		// 3. Retrieve the collection record.
		collection, err := s.catalog.metaDomain.CollectionDb(txCtx).GetCollectionWithoutMetadata(&req.CollectionId, nil, nil)
		if err != nil {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: failed to get collection", zap.Error(err))
			return err
		}
		if collection == nil {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: collection not found", zap.String("collection_id", req.CollectionId))
			return common.ErrCollectionNotFound
		}

		// 4. Atomically advance the completion offset and mark the heap entry as pending.
		err = s.catalog.metaDomain.AttachedFunctionDb(txCtx).UpdateCompletionOffsetAndHeapEntry(attachedFunction.ID, req.CollectionId, newOffset)
		if err != nil {
			if errors.Is(err, common.ErrAttachedFunctionOffsetWouldRegress) {
				log.Error("TryFinishAsyncAttachedFunctionInvocation: completion offset would regress",
					zap.String("attached_function_id", attachedFunction.ID.String()),
					zap.Int64("new_offset", newOffset))
				return err
			}
			log.Error("TryFinishAsyncAttachedFunctionInvocation: failed to update completion offset", zap.Error(err))
			return err
		}

		// 5. Decide whether the collection has advanced beyond the new completion offset and needs repair.
		if collection.LogPosition > newOffset {
			response.Result = &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_NeedsRepair_{
				NeedsRepair: &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_NeedsRepair{
					CurrentCollectionLogOffset: uint64(collection.LogPosition),
				},
			}
		} else {
			response.Result = &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_Success_{
				Success: &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_Success{
					UpdatedCompletionOffset: req.NewCompletionOffset,
				},
			}
		}

		return nil
	})

	if err != nil {
		return nil, err
	}

	return response, nil
}

// FinalizeAsyncAttachedFunctionRepair finalizes a repair by clearing the heap_entry_pending flag for the
// specified attached function. It is idempotent: repeated calls with the same request succeed.
func (s *Coordinator) FinalizeAsyncAttachedFunctionRepair(ctx context.Context, req *coordinatorpb.FinalizeAsyncAttachedFunctionRepairRequest) (*coordinatorpb.FinalizeAsyncAttachedFunctionRepairResponse, error) {
	log := log.With(zap.String("method", "FinalizeAsyncAttachedFunctionRepair"))

	attachedFunctionID, err := uuid.Parse(req.AttachedFunctionId)
	if err != nil {
		log.Error("FinalizeAsyncAttachedFunctionRepair: invalid attached_function_id", zap.Error(err))
		return nil, status.Errorf(codes.InvalidArgument, "invalid attached_function_id: %v", err)
	}

	err = s.catalog.metaDomain.AttachedFunctionDb(ctx).UpdateHeapEntryPending(attachedFunctionID, false)
	if err != nil {
		log.Error("FinalizeAsyncAttachedFunctionRepair: failed to update heap entry pending", zap.Error(err))
		return nil, err
	}

	log.Info("FinalizeAsyncAttachedFunctionRepair: completed successfully",
		zap.String("attached_function_id", attachedFunctionID.String()))

	return &coordinatorpb.FinalizeAsyncAttachedFunctionRepairResponse{}, nil
}

